     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinPrioridadPqr(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(PqrPeer::DATABASE_NAME);
        }

        PqrPeer::addSelectColumns($criteria);
        $startcol = PqrPeer::NUM_HYDRATE_COLUMNS;
        PrioridadPqrPeer::addSelectColumns($criteria);

        $criteria->addJoin(PqrPeer::PRIORIDADPQR_ID, PrioridadPqrPeer::PRIORIDADPQR_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BasePqrPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = PqrPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = PqrPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = PqrPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                PqrPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = PrioridadPqrPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = PrioridadPqrPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = PrioridadPqrPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    PrioridadPqrPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (Pqr) to $obj2 (PrioridadPqr)
                $obj2->addPqr($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


