        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(PqrPeer::DATABASE_NAME);
        }

        PqrPeer::addSelectColumns($criteria);
        $startcol2 = PqrPeer::NUM_HYDRATE_COLUMNS;

        CategoriaPqrPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + CategoriaPqrPeer::NUM_HYDRATE_COLUMNS;

        UsuarioPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + UsuarioPeer::NUM_HYDRATE_COLUMNS;

        EstadoPqrPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + EstadoPqrPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(PqrPeer::CATEGORIAPQR_ID, CategoriaPqrPeer::CATEGORIAPQR_ID, $join_behavior);

        $criteria->addJoin(PqrPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID, $join_behavior);

        $criteria->addJoin(PqrPeer::ESTADOPQR_ID, EstadoPqrPeer::ESTADOPQR_ID, $join_behavior);

