                $obj1 = new $cls();
                $obj1->hydrate($row);
                PqrPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined CategoriaPqr rows

                $key2 = CategoriaPqrPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = CategoriaPqrPeer::getInstanceFromPool($key2);
