                $obj3->addPqr($obj1);

            } // if joined row is not null

                // Add objects for joined EstadoPqr rows

                $key4 = EstadoPqrPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = EstadoPqrPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
