                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    EstadoPqrPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (Pqr) to the collection in $obj4 (EstadoPqr)
                $obj4->addPqr($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


